627	+//! Where a declaration comes from, read from its file's path: the one place both lanes decide it (ADR 0028, Ambient).
628	+//!
629	+//! Relevance reads [`Origin::is_ambient`], the checker merge reads [`Origin::React`] (what `@types/react` declares it
630	+//! leaves to the inheritance layers) and the dependency loader leaves [`Origin::React`] files to the resolver's React
631	+//! handling. Each reads its own question of the same answer, so a path cannot be ambient to one and plain to another.
632	+
633	+/// Where a declaration's file is.
634	+#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
635	+pub enum Origin {
636	+    /// React's own types: `@types/react`, or the `react` package.
637	+    React,
638	+    /// The DOM types react-aria shares across its packages: `@react-types/shared/src/dom.d.ts`.
639	+    SharedDom,
640	+    /// Any other file under `node_modules`.
641	+    Dependency,
642	+    /// The project's own files.
643	+    Project,
644	+}
645	+
646	+impl Origin {
647	+    /// Whether what the file declares is ambient: what every element has, decided by path, never by name.
648	+    ///
649	+    /// ```
650	+    /// use caliper_docgen_core::origin::{Origin, declaration_origin};
651	+    ///
652	+    /// assert!(declaration_origin("/p/node_modules/@types/react/index.d.ts").is_ambient());
653	+    /// assert!(declaration_origin("/p/node_modules/@react-types/shared/src/dom.d.ts").is_ambient());
654	+    /// assert_eq!(declaration_origin("/p/node_modules/@mantine/core/lib/index.d.ts"), Origin::Dependency);
655	+    /// assert!(!declaration_origin("/p/src/Button.tsx").is_ambient());
656	+    /// ```
657	+    pub fn is_ambient(self) -> bool {
658	+        match self {
659	+            Self::React | Self::SharedDom => true,
660	+            Self::Dependency | Self::Project => false,
661	+        }
662	+    }
663	+}
664	+
665	+/// The [`Origin`] of a declaration in `file`, an absolute path with `/` separators.
666	+pub fn declaration_origin(file: &str) -> Origin {
667	+    if file.contains("/@types/react/") || file.contains("/node_modules/react/") {
668	+        Origin::React
669	+    } else if file
670	+        .rsplit_once("/@react-types/shared/src/")
671	+        .is_some_and(|(_, name)| matches!(name, "dom.d.ts" | "dom.d.mts" | "dom.d.cts"))
672	+    {
673	+        Origin::SharedDom
674	+    } else if file.contains("/node_modules/") {
675	+        Origin::Dependency
676	+    } else {
677	+        Origin::Project
678	+    }
679	+}
