458	    fn is_read(&self, member: NodeId) -> bool {
459	        let (parent, child) = self.through_wrappers(member);
460	        let (parent, child) = match self.nodes.kind(parent) {
461	            // `props?.x`: the chain is what is called, written or deleted (`delete props?.x`, `(props?.f)()`).
