466	            AstKind::CallExpression(call) => call.callee.span() != child,
467	            AstKind::TaggedTemplateExpression(tagged) => tagged.tag.span() != child,
468	            AstKind::AssignmentExpression(assignment) => assignment.left.span() != child,
469	            AstKind::UnaryExpression(unary) => unary.operator != UnaryOperator::Delete,
